cd .skilled/skills/system-deep-loop/deep-research && python3 - <<'EOF'
import re, os
files = ["README.md","ROUTER.md","SKILL.md","assets/deep-research-dashboard.md","assets/deep-research-strategy.md","references/convergence/convergence-graph.md","references/convergence/convergence-recovery.md","references/convergence/convergence-reference-only.md"]
pat = re.compile(r'\[[^\]]*\]\(([^)]+)\)')
for f in files:
    base = os.path.dirname(f)
    text = open(f).read().splitlines()
    for i, line in enumerate(text, 1):
        for m in pat.finditer(line):
            target = m.group(1)
            if target.startswith(('http','#','mailto')):
                continue
            p = os.path.normpath(os.path.join(base, target.split('#')[0]))
            if not os.path.exists(p):
                print(f"{f}:{i}: MISSING {target} -> {p}")
EOF

